          "ምክንያቱም ህጎች ማንኛውንም የዘረመል ሙከራዎችን በጥብቅ ስለሚከለክሉ።",
          "ምክንያቱም የመጀመሪያው ንጥረ ነገር በቁሳዊው ዓለም ውስጥ በድንገት እና ያለ ምክንያት ስለሚጠፋ።"
